// Grouped from 4 flat commands (Birthday/slashcommand-birthday-channel.js, Birthday/slashcommand-birthday-list.js, Birthday/slashcommand-birthday-remove.js, Birthday/slashcommand-birthday-set.js). Generated by scripts/group-commands.js.
const { ChatInputCommandInteraction } = require('discord.js');
const DiscordBot = require('../../client/DiscordBot');
const ApplicationCommand = require('../../structure/ApplicationCommand');
const { t, resolveLocale } = require('../../utils/i18n');
const { PermissionFlagsBits } = require('discord.js');
const { successEmbed, errorEmbed, infoEmbed } = require('../../utils/embeds');

const SUB_PERMS = {
    "birthday-channel": "32",
};

const handlers = {
    "birthday-channel": async (client, interaction) => {
        const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
        const ch = interaction.options.getChannel('channel', true);
        client.database.set('birthday-channel-' + interaction.guildId, ch.id);
        return interaction.reply({ embeds: [successEmbed(locale, t('birthday.channel', { locale, vars: { ch: ch.id } }))] });
    },
    "birthday-list": async (client, interaction) => {
        const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
        const all = client.database.get('birthdays-' + interaction.guildId) || {};
        const ids = Object.keys(all);
        if (!ids.length) return interaction.reply({ embeds: [infoEmbed(locale, t('birthday.empty', { locale }))], ephemeral: true });
        return interaction.reply({ embeds: [infoEmbed(locale, ids.slice(0, 20).map(id => '<@' + id + '> — ' + all[id]).join('\n'))] });
    },
    "birthday-remove": async (client, interaction) => {
        const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
        const all = client.database.get('birthdays-' + interaction.guildId) || {};
        delete all[interaction.user.id];
        client.database.set('birthdays-' + interaction.guildId, all);
        return interaction.reply({ embeds: [successEmbed(locale, t('birthday.removed', { locale }))] });
    },
    "birthday-set": async (client, interaction) => {
        const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
        const date = interaction.options.getString('date', true);
        if (!/^\d{2}\/\d{2}$/.test(date)) return interaction.reply({ embeds: [errorEmbed(locale, t('birthday.invalid', { locale }))], ephemeral: true });
        const all = client.database.get('birthdays-' + interaction.guildId) || {};
        all[interaction.user.id] = date;
        client.database.set('birthdays-' + interaction.guildId, all);
        return interaction.reply({ embeds: [successEmbed(locale, t('birthday.set', { locale, vars: { date } }))] });
    },
};

module.exports = new ApplicationCommand({
    command: {
        name: "birthday", description: "🎂 Birthdays.", type: 1,
        description_localizations: { 'pt-BR': "🎂 Aniversários." },
        options: [
            {
                name: "birthday-channel",
                description: "🎂 Sets the birthday announcement channel.",
                description_localizations: {"pt-BR":"🎂 Define canal de aniversários."},
                type: 1,
                options: [{"name":"channel","name_localizations":{"pt-BR":"canal"},"description":"Channel","description_localizations":{"pt-BR":"Canal"},"type":7,"required":true}],
            },
            {
                name: "birthday-list",
                description: "🎂 Lists upcoming birthdays.",
                description_localizations: {"pt-BR":"🎂 Lista próximos aniversários."},
                type: 1,
                options: [],
            },
            {
                name: "birthday-remove",
                description: "🎂 Removes your birthday.",
                description_localizations: {"pt-BR":"🎂 Remove seu aniversário."},
                type: 1,
                options: [],
            },
            {
                name: "birthday-set",
                description: "🎂 Sets your birthday (DD/MM).",
                description_localizations: {"pt-BR":"🎂 Define seu aniversário (DD/MM)."},
                type: 1,
                options: [{"name":"date","name_localizations":{"pt-BR":"data"},"description":"DD/MM","description_localizations":{"pt-BR":"DD/MM"},"type":3,"required":true}],
            },
        ],
    },
    /**
     * @param {DiscordBot} client
     * @param {ChatInputCommandInteraction} interaction
     */
    run: async (client, interaction) => {
        const sub = interaction.options.getSubcommand();
        const need = SUB_PERMS[sub];
        if (need) {
            let ok = false;
            try { ok = !!interaction.memberPermissions && interaction.memberPermissions.has(BigInt(need)); } catch { ok = false; }
            if (!ok) {
                const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
                return interaction.reply({ content: t('handler.missing_permissions', { locale }), ephemeral: true });
            }
        }
        const fn = handlers[sub];
        if (!fn) {
            return interaction.reply({ content: 'Unknown subcommand: ' + sub, ephemeral: true });
        }
        return fn(client, interaction);
    },
}).toJSON();
